95	/****************************************************************************
96	 * Name: gpio_set_output
97	 ****************************************************************************/
98	
99	static void gpio_set_output(int pin)
100	{
101	  uint32_t cfg = getreg32(BK7258_GPIO_CFG(pin));
102	
103	  cfg &= ~GPIO_CFG_SECOND_FUNC;  /* GPIO mode (bit6 = 0) */
104	  cfg &= ~GPIO_CFG_OUTPUT_EN;    /* output enable (bit3 active-low: 0 = on) */
105	  cfg &= ~GPIO_CFG_INPUT_EN;     /* input disable (bit2 active-high: 0 = off) */
106	  putreg32(cfg, BK7258_GPIO_CFG(pin));
107	}
108	
109	/****************************************************************************
110	 * Name: gpio_write
111	 ****************************************************************************/
112	
113	static void gpio_write(int pin, int val)
114	{
115	  uint32_t cfg = getreg32(BK7258_GPIO_CFG(pin));
116	
117	  if (val)
118	    {
119	      cfg |= GPIO_CFG_OUTPUT;
120	    }
121	  else
122	    {
123	      cfg &= ~GPIO_CFG_OUTPUT;
124	    }
125	
126	  putreg32(cfg, BK7258_GPIO_CFG(pin));
127	}
