149	 ****************************************************************************/
150	
151	static void lcd_send_cmd(uint8_t cmd)
152	{
153	  gpio_write(LCD_PIN_DC, 0);
154	  gpio_write(LCD_PIN_CS, 0);
155	  spi_write_byte(cmd);
156	  gpio_write(LCD_PIN_CS, 1);
157	}
158	
159	static void lcd_send_data(const uint8_t *data, int len)
160	{
161	  int i;
162	
163	  gpio_write(LCD_PIN_DC, 1);
164	  gpio_write(LCD_PIN_CS, 0);
165	  for (i = 0; i < len; i++)
166	    {
167	      spi_write_byte(data[i]);
168	    }
169	
170	  gpio_write(LCD_PIN_CS, 1);
171	}
172	
173	static void lcd_send_cmd_data(uint8_t cmd, const uint8_t *data, int len)
174	{
175	  lcd_send_cmd(cmd);
176	  if (len > 0)
177	    {
178	      lcd_send_data(data, len);
179	    }
180	}
