265	/****************************************************************************
266	 * Name: lcd_fill_rect
267	 *
268	 * Description:
269	 *   Fill a rectangle (x0,y0)-(x1,y1) with a single RGB565 color.
270	 *   Much smaller than full-screen fill — avoids millions of bit-bangs.
271	 *
272	 ****************************************************************************/
273	
274	static void lcd_fill_rect(uint16_t x0, uint16_t y0,
275	                          uint16_t x1, uint16_t y1,
276	                          uint16_t color)
277	{
278	  uint8_t ca[4];
279	  uint8_t ra[4];
280	  uint8_t hi = (color >> 8) & 0xff;
281	  uint8_t lo = color & 0xff;
282	  int npix = (int)(x1 - x0 + 1) * (int)(y1 - y0 + 1);
283	  int i;
284	
285	  /* CASET */
286	
287	  ca[0] = (x0 >> 8) & 0xff;
288	  ca[1] = x0 & 0xff;
289	  ca[2] = (x1 >> 8) & 0xff;
290	  ca[3] = x1 & 0xff;
291	  lcd_send_cmd_data(0x2a, ca, 4);
292	
293	  /* RASET */
294	
295	  ra[0] = (y0 >> 8) & 0xff;
296	  ra[1] = y0 & 0xff;
297	  ra[2] = (y1 >> 8) & 0xff;
298	  ra[3] = y1 & 0xff;
299	  lcd_send_cmd_data(0x2b, ra, 4);
300	
301	  /* RAMWR + pixel data */
302	
303	  lcd_send_cmd(0x2c);
304	  gpio_write(LCD_PIN_DC, 1);
305	  gpio_write(LCD_PIN_CS, 0);
306	  for (i = 0; i < npix; i++)
307	    {
308	      spi_write_byte(hi);
309	      spi_write_byte(lo);
310	    }
311	
312	  gpio_write(LCD_PIN_CS, 1);
313	}
