382	/****************************************************************************
383	 * Name: lcdtest_scan
384	 *
385	 * Description:
386	 *   Scan GPIO 0-47 for the LCD power enable pin.
387	 *   Strategy: cumulative — pull each pin high and leave it high, so that
388	 *   if multiple pins need to be high simultaneously the condition is met.
389	 *   P25 (backlight) is held high throughout.  UART console pins (10, 11)
390	 *   and LCD signal pins (2-5, 29) are skipped to keep the console and
391	 *   SPI bus alive.
392	 *
393	 ****************************************************************************/
394	
395	static int lcdtest_scan(void)
396	{
397	  int pin;
398	
399	  /* Backlight on first */
400	
401	  gpio_set_output(LCD_PIN_BL);
402	  gpio_write(LCD_PIN_BL, 1);
403	
404	  syslog(LOG_INFO,
405	         "[scan] backlight P25 high, scanning GPIO 0-47 ...\n");
406	
407	  for (pin = 0; pin <= 47; pin++)
408	    {
409	      /* Skip UART0 console: RX=10, TX=11 */
410	
411	      if (pin == 10 || pin == 11)
412	        {
413	          syslog(LOG_INFO,
414	                 "[scan] pin=%d skipped (UART0 console)\n", pin);
415	          continue;
416	        }
417	
418	      /* Skip LCD signal pins already in use */
419	
420	      if (pin == LCD_PIN_SCLK || pin == LCD_PIN_CS ||
421	          pin == LCD_PIN_MOSI || pin == LCD_PIN_DC  ||
422	          pin == LCD_PIN_RST   || pin == LCD_PIN_BL)
423	        {
424	          syslog(LOG_INFO,
425	                 "[scan] pin=%d skipped (LCD signal)\n", pin);
426	          continue;
427	        }
428	
429	      /* Skip SWD debug port: SWCLK=20, SWDIO=21 */
430	
431	      if (pin == 20 || pin == 21)
432	        {
433	          syslog(LOG_INFO,
434	                 "[scan] pin=%d skipped (SWD debug)\n", pin);
435	          continue;
436	        }
437	
438	      gpio_set_output(pin);
439	      gpio_write(pin, 1);
440	      up_mdelay(800);
441	
442	      syslog(LOG_INFO, "[scan] pin=%d high\n", pin);
443	    }
444	
445	  syslog(LOG_INFO,
446	         "[scan] done - check screen for any change\n");
447	
448	  return OK;
449	}
