149	 * Name: lcd_send_cmd / lcd_send_data / lcd_send_cmd_data
150	 ****************************************************************************/
151	
152	static void lcd_send_cmd(uint8_t cmd)
153	{
154	  gpio_write(LCD_PIN_DC, 0);
155	  gpio_write(LCD_PIN_CS, 0);
156	  spi_write_byte(cmd);
157	  gpio_write(LCD_PIN_CS, 1);
158	}
159	
160	static void lcd_send_data(const uint8_t *data, int len)
161	{
162	  int i;
163	
164	  gpio_write(LCD_PIN_DC, 1);
165	  gpio_write(LCD_PIN_CS, 0);
166	  for (i = 0; i < len; i++)
167	    {
168	      spi_write_byte(data[i]);
169	    }
170	
171	  gpio_write(LCD_PIN_CS, 1);
172	}
173	
174	static void lcd_send_cmd_data(uint8_t cmd, const uint8_t *data, int len)
175	{
176	  lcd_send_cmd(cmd);
177	  if (len > 0)
178	    {
179	      lcd_send_data(data, len);
180	    }
181	}
