361	
362	  /* --- Stage B: reset + init --- */
363	
364	  syslog(LOG_INFO,
365	         "[lcdtest] Stage B: RST(P29) reset + GC9D01 init\n");
366	
367	  gpio_set_output(LCD_PIN_SCLK);
368	  gpio_set_output(LCD_PIN_CS);
369	  gpio_set_output(LCD_PIN_MOSI);
370	  gpio_set_output(LCD_PIN_DC);
371	  gpio_set_output(LCD_PIN_RST);
372	
373	  gpio_write(LCD_PIN_CS, 1);
374	  gpio_write(LCD_PIN_DC, 1);
375	  gpio_write(LCD_PIN_SCLK, 0);
376	  gpio_write(LCD_PIN_MOSI, 0);
377	
378	  gpio_write(LCD_PIN_RST, 0);
379	  up_mdelay(10);
380	  gpio_write(LCD_PIN_RST, 1);
381	  up_mdelay(120);
382	
383	  lcd_init_sequence(true);
384	
385	  syslog(LOG_INFO,
