403	/****************************************************************************
404	 * Name: lcdtest_scan
405	 *
406	 * Description:
407	 *   Scan GPIO 0-47 for the LCD power enable pin.
408	 *   Strategy: cumulative — pull each pin high and leave it high, so that
409	 *   if multiple pins need to be high simultaneously the condition is met.
410	 *   P25 (backlight) is held high throughout.  UART console pins (10, 11)
411	 *   and LCD signal pins (2-5, 29) are skipped to keep the console and
412	 *   SPI bus alive.
413	 *
414	 ****************************************************************************/
415	
416	static int lcdtest_scan(void)
417	{
418	  int pin;
419	
420	  /* Backlight on first */
421	
422	  gpio_set_output(LCD_PIN_BL);
423	  gpio_write(LCD_PIN_BL, 1);
424	
425	  syslog(LOG_INFO,
426	         "[scan] backlight P25 high, scanning GPIO 0-47 ...\n");
427	
428	  for (pin = 0; pin <= 47; pin++)
429	    {
430	      /* Skip UART0 console: RX=10, TX=11 */
431	
432	      if (pin == 10 || pin == 11)
433	        {
434	          syslog(LOG_INFO,
435	                 "[scan] pin=%d skipped (UART0 console)\n", pin);
436	          continue;
437	        }
438	
439	      /* Skip LCD signal pins already in use */
440	
441	      if (pin == LCD_PIN_SCLK || pin == LCD_PIN_CS ||
442	          pin == LCD_PIN_MOSI || pin == LCD_PIN_DC  ||
443	          pin == LCD_PIN_RST   || pin == LCD_PIN_BL)
444	        {
445	          syslog(LOG_INFO,
446	                 "[scan] pin=%d skipped (LCD signal)\n", pin);
447	          continue;
448	        }
449	
450	      /* Skip SWD debug port: SWCLK=20, SWDIO=21 */
451	
452	      if (pin == 20 || pin == 21)
453	        {
454	          syslog(LOG_INFO,
455	                 "[scan] pin=%d skipped (SWD debug)\n", pin);
456	          continue;
457	        }
458	
459	      gpio_set_output(pin);
460	      gpio_write(pin, 1);
461	      up_mdelay(800);
462	
463	      syslog(LOG_INFO, "[scan] pin=%d high\n", pin);
464	    }
465	
466	  syslog(LOG_INFO,
467	         "[scan] done - check screen for any change\n");
468	
469	  return OK;
470	}
