472	/****************************************************************************
473	 * Name: lcdtest_pwr
474	 *
475	 * Description:
476	 *   Full power-on sequence with configurable GPIO range for binary-search
477	 *   identification of the LCD power enable pin.
478	 *
479	 *   Usage: lcdtest pwr [lo] [hi]
480	 *     lo..hi  — decimal GPIO range to drive high (default 0..52)
481	 *
482	 *   Always skips: 2,3,4,5,25,29 (LCD)  10,11 (UART)  7,8 (motor)
483	 *                 20,21 (SWD)  38,39 (LEDs)
484	 *
485	 ****************************************************************************/
486	
487	static int lcdtest_pwr(int lo, int hi)
488	{
489	  int pin;
490	  int count = 0;
491	  int off = 0;
492	  char pinbuf[256];
493	
494	  /* Step 1: drive GPIO lo..hi high, skip reserved pins.
495	   * Collect the actual pin list for the syslog dump.
496	   */
497	
498	  syslog(LOG_INFO,
499	         "[pwr] step1: GPIO %d-%d high (skip reserved)\n",
500	         lo, hi);
501	
502	  for (pin = lo; pin <= hi; pin++)
503	    {
504	      /* LCD signals */
505	
506	      if (pin == 2 || pin == 3 || pin == 4 || pin == 5 ||
507	          pin == 25 || pin == 29)
508	        {
509	          continue;
510	        }
511	
512	      /* UART0 console */
513	
514	      if (pin == 10 || pin == 11)
515	        {
516	          continue;
517	        }
518	
519	      /* Vibration motor */
520	
521	      if (pin == 7 || pin == 8)
522	        {
523	          continue;
524	        }
525	
526	      /* Indicator LEDs */
527	
528	      if (pin == 38 || pin == 39)
529	        {
530	          continue;
531	        }
532	
533	      /* SWD debug port: SWCLK=20, SWDIO=21 */
534	
535	      if (pin == 20 || pin == 21)
536	        {
537	          continue;
538	        }
539	
540	      gpio_set_output(pin);
541	      gpio_write(pin, 1);
542	      count++;
543	
544	      if (off < (int)sizeof(pinbuf) - 8)
545	        {
546	          off += snprintf(pinbuf + off, sizeof(pinbuf) - off,
547	                          " %d", pin);
548	        }
549	    }
550	
551	  pinbuf[off] = '\0';
552	
553	  /* Print which pins were actually driven high */
554	
555	  syslog(LOG_INFO,
556	         "[pwr] driven high (%d pins):%s\n", count, pinbuf);
557	
558	  /* Step 2: wait for power rails to settle */
559	
560	  syslog(LOG_INFO, "[pwr] step2: wait 50 ms ...\n");
561	  up_mdelay(50);
562	
563	  /* Step 3: backlight on */
564	
565	  syslog(LOG_INFO, "[pwr] step3: backlight P25 high\n");
566	  gpio_set_output(LCD_PIN_BL);
567	  gpio_write(LCD_PIN_BL, 1);
568	
569	  /* Step 4: hardware reset */
570	
571	  syslog(LOG_INFO,
572	         "[pwr] step4: RST(P29) low 15 ms then high\n");
573	  gpio_set_output(LCD_PIN_RST);
574	  gpio_write(LCD_PIN_RST, 0);
575	  up_mdelay(15);
576	  gpio_write(LCD_PIN_RST, 1);
577	  up_mdelay(120);
578	
579	  /* Step 5: GC9D01 init sequence */
580	
581	  syslog(LOG_INFO, "[pwr] step5: GC9D01 init sequence\n");
582	  lcd_init_sequence(true);
583	
584	  /* Step 6: clear screen to black */
585	
586	  syslog(LOG_INFO, "[pwr] step6: fill screen black\n");
587	  lcd_fill_rect(0, 0, LCD_WIDTH - 1, LCD_HEIGHT - 1, 0x0000);
588	
589	  /* Step 7: draw 40x40 red square at (60,60) */
590	
591	  syslog(LOG_INFO,
592	         "[pwr] step7: fill 40x40 red at (60,60)\n");
593	  lcd_fill_rect(60, 60,
594	                60 + SQ_SIZE - 1, 60 + SQ_SIZE - 1,
595	                0xf800);
596	
597	  syslog(LOG_INFO,
598	         "[pwr] done (%d pins driven) - "
599	         "screen should show red on black\n",
600	         count);
601	  return OK;
602	}
