{
  int old_cx = 80 + g_emo_gaze;
  int new_cx = 80 + dx;

  /* Erase old pupil + old highlight with iris colour */

  lcd_fill_circle(old_cx, 80, EMO_PUPIL_R + 1, 0x07ff);
  lcd_fill_circle(old_cx - 10, 68, EMO_HL_R + 1, 0x07ff);

