/****************************************************************************
 * BK7258 analog audio ADC dual-channel (L=M1, R=M2) polling capture.
 *
 * Register-level driver — no DMA, no interrupts.
 * Source: Armino aud_adc_driver.c + aud_hal.c + sys_audio_driver.c
 ****************************************************************************/

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <nuttx/config.h>

#include <math.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <string.h>
#include <debug.h>

#include <nuttx/arch.h>
#include <nuttx/nuttx.h>

/****************************************************************************
 * Inline Register Access (self-contained, no arch dependency)
 ****************************************************************************/

static inline uint32_t aud_getreg(uintptr_t addr)
{
  return *(volatile uint32_t *)addr;
}

static inline void aud_putreg(uint32_t val, uintptr_t addr)
{
  *(volatile uint32_t *)addr = val;
}

/****************************************************************************
 * Pre-processor Definitions — Base Addresses
 ****************************************************************************/

#define AUD_BASE           0x47800000
#define SYS_BASE           0x44010000

/****************************************************************************
 * Audio Digital Register Offsets (from Armino aud_reg.h)
 ****************************************************************************/

#define AUD_CLK_CONTROL    (AUD_BASE + 0x08)
#define AUD_ADC_CONFIG_0   (AUD_BASE + 0x10)
#define AUD_FIFO_CONFIG    (AUD_BASE + 0x28)
#define AUD_FIFO_STATUS    (AUD_BASE + 0x38)
#define AUD_ADC_FIFO_PORT  (AUD_BASE + 0x44)
#define AUD_EXTEND_CFG     (AUD_BASE + 0x60)
#define AUD_ADC_FRACMOD    (AUD_BASE + 0x68)
#define AUD_CONFIG         (AUD_BASE + 0xc0)

/****************************************************************************
 * AUD_CLK_CONTROL bits
 ****************************************************************************/

#define AUD_ADC_SOFT_RESET (1u << 0)
#define AUD_ADC_CLK_GATE   (1u << 1)

/****************************************************************************
 * AUD_ADC_CONFIG_0 bits
 ****************************************************************************/

#define AUD_ADC_HPF2_BYP   (1u << 16)
#define AUD_ADC_HPF1_BYP   (1u << 17)
#define AUD_ADC_GAIN_SHIFT 18
#define AUD_ADC_GAIN_MASK  (0x3fu << 18)
#define AUD_ADC_GAIN_0DB   (0x2du << 18)
#define AUD_ADC_EDGE       (1u << 24)

/****************************************************************************
 * AUD_FIFO_STATUS bits
 ****************************************************************************/

#define AUD_ADC_FIFO_EMPTY (1u << 14)

/****************************************************************************
 * AUD_CONFIG bits
 ****************************************************************************/

#define AUD_RATE_ADC_SHIFT 0
#define AUD_RATE_ADC_MASK  (0x3u << 0)
#define AUD_RATE_ADC_16K   (0x1u << 0)
#define AUD_ADC_ENABLE     (1u << 3)
#define AUD_LINEIN_ENABLE  (1u << 5)
#define AUD_APLL_SEL       (1u << 8)

/****************************************************************************
 * AUD_EXTEND_CFG bits
 ****************************************************************************/

#define AUD_ADC_FRAC_MANUAL (1u << 1)

/****************************************************************************
 * Analog Registers (SYS_BASE + offset)
 *
 * ANA_REG18 (0x52*4): audio/ADC/mic bias enable
 * ANA_REG19 (0x53*4): MIC1 enable, reset, diff mode, gain
 * ANA_REG20 (0x54*4): diffen, DAC stuff
 * ANA_REG27 (0x5B*4): MIC2 enable (BK7258 specific)
 ****************************************************************************/

#define ANA_REG18          (SYS_BASE + 0x52 * 4)
#define ANA_REG19          (SYS_BASE + 0x53 * 4)
#define ANA_REG20          (SYS_BASE + 0x54 * 4)
#define ANA_REG27          (SYS_BASE + 0x5b * 4)

/* ANA_REG18 bits */

#define ANA_ENAUDBIAS      (1u << 3)
#define ANA_ENADCBIAS      (1u << 4)
#define ANA_ENMICBIAS      (1u << 5)

/* ANA_REG19 bits */

#define ANA_MIC_SINGLE_EN  (1u << 13)  /* 1=single-end, 0=diff */
#define ANA_MICEN          (1u << 28)
#define ANA_MIC_RST        (1u << 29)

/* ANA_REG20 bits */

#define ANA_DIFFEN         (1u << 13)

/****************************************************************************
 * Sample counts
 ****************************************************************************/

#define MIC_N_SAMPLES      4096

/****************************************************************************
 * Private Data
 ****************************************************************************/

static int16_t g_mic_left[MIC_N_SAMPLES];
static int16_t g_mic_right[MIC_N_SAMPLES];

/****************************************************************************
 * Private Functions
 ****************************************************************************/

/****************************************************************************
 * Name: audio_init
 *
 * Description:
 *   Initialise BK7258 audio ADC for dual-channel differential capture
 *   at 16 kHz.  Sequence extracted from Armino aud_adc_driver.c +
 *   sys_audio_driver.c.
 *
 ****************************************************************************/

static void audio_init(void)
{
  uint32_t val;

  syslog(LOG_INFO, "[mic] init: clock + soft reset\n");

  /* Step 1: Enable audio APB clock gate.
   * AUD_CLK_CONTROL bit[1] = 0 to enable clock.
   */

  val = aud_getreg(AUD_CLK_CONTROL);
  val &= ~AUD_ADC_CLK_GATE;
  aud_putreg(val, AUD_CLK_CONTROL);

  /* Step 2: Soft reset the audio digital block */

  val = aud_getreg(AUD_CLK_CONTROL);
  val |= AUD_ADC_SOFT_RESET;
  aud_putreg(val, AUD_CLK_CONTROL);
  up_mdelay(1);
  val &= ~AUD_ADC_SOFT_RESET;
  aud_putreg(val, AUD_CLK_CONTROL);

  /* Step 3: Select XTAL clock (APLL not supported on BK7258) */

  val = aud_getreg(AUD_CONFIG);
  val &= ~AUD_APLL_SEL;
  aud_putreg(val, AUD_CONFIG);

  syslog(LOG_INFO, "[mic] init: analog power + mic bias\n");

  /* Step 4: Enable audio bias, ADC bias, mic bias (ANA_REG18) */

  val = aud_getreg(ANA_REG18);
  val |= ANA_ENAUDBIAS | ANA_ENADCBIAS | ANA_ENMICBIAS;
  aud_putreg(val, ANA_REG18);

  /* Step 5: Enable MIC1 (ANA_REG19 bit[28]) */

  val = aud_getreg(ANA_REG19);
  val |= ANA_MICEN;
  aud_putreg(val, ANA_REG19);

  /* Step 6: Enable MIC2 (ANA_REG27 — BK7258 specific) */

  aud_putreg(0x91800006, ANA_REG27);

  syslog(LOG_INFO, "[mic] init: differential mode + mic reset\n");

  /* Step 7: Differential mode — ANA_REG19 bit[13] = 0 (default) */

  val = aud_getreg(ANA_REG19);
  val &= ~ANA_MIC_SINGLE_EN;
  aud_putreg(val, ANA_REG19);

  /* Also set ANA_REG20 diffen for good measure */

  val = aud_getreg(ANA_REG20);
  val |= ANA_DIFFEN;
  aud_putreg(val, ANA_REG20);

  /* Step 8: MIC reset pulse */

  val = aud_getreg(ANA_REG19);
  val |= ANA_MIC_RST;
  aud_putreg(val, ANA_REG19);
  up_mdelay(10);
  val &= ~ANA_MIC_RST;
  aud_putreg(val, ANA_REG19);

  syslog(LOG_INFO, "[mic] init: ADC config\n");

  /* Step 9: ADC digital config — gain 0dB, bypass HPF, rising edge */

  val = aud_getreg(AUD_ADC_CONFIG_0);
  val &= ~AUD_ADC_GAIN_MASK;
  val |= AUD_ADC_GAIN_0DB;
  val &= ~AUD_ADC_EDGE;
  val |= AUD_ADC_HPF1_BYP | AUD_ADC_HPF2_BYP;
  aud_putreg(val, AUD_ADC_CONFIG_0);

  /* Step 10: Sample rate 16kHz, XTAL fixed divider */

  val = aud_getreg(AUD_CONFIG);
  val &= ~AUD_RATE_ADC_MASK;
  val |= AUD_RATE_ADC_16K;
  aud_putreg(val, AUD_CONFIG);

  /* Disable ADC fractional divider (use fixed path) */

  val = aud_getreg(AUD_EXTEND_CFG);
  val &= ~AUD_ADC_FRAC_MANUAL;
  aud_putreg(val, AUD_EXTEND_CFG);

  syslog(LOG_INFO, "[mic] init: enable ADC\n");

  /* Step 11: Enable ADC + line-in */

  val = aud_getreg(AUD_CONFIG);
  val |= AUD_ADC_ENABLE | AUD_LINEIN_ENABLE;
  aud_putreg(val, AUD_CONFIG);

  up_mdelay(50);

  syslog(LOG_INFO, "[mic] init done\n");
}

/****************************************************************************
 * Name: audio_deinit
 *
 * Description:
 *   Disable ADC, power down analog front-end.
 *
 ****************************************************************************/

static void audio_deinit(void)
{
  uint32_t val;

  syslog(LOG_INFO, "[mic] deinit\n");

  /* Disable ADC + line-in */

  val = aud_getreg(AUD_CONFIG);
  val &= ~(AUD_ADC_ENABLE | AUD_LINEIN_ENABLE);
  aud_putreg(val, AUD_CONFIG);

  /* Disable mic bias, ADC bias, audio bias */

  val = aud_getreg(ANA_REG18);
  val &= ~(ANA_ENAUDBIAS | ANA_ENADCBIAS | ANA_ENMICBIAS);
  aud_putreg(val, ANA_REG18);

  /* Gate the clock */

  val = aud_getreg(AUD_CLK_CONTROL);
  val |= AUD_ADC_CLK_GATE;
  aud_putreg(val, AUD_CLK_CONTROL);
}

/****************************************************************************
 * Name: audio_capture
 *
 * Description:
 *   Poll ADC FIFO and capture N sample pairs (L+R interleaved).
 *   Each AUD_ADC_FIFO_PORT read returns L in [15:0], R in [31:16].
 *
 ****************************************************************************/

static int audio_capture(int n)
{
  int count = 0;
  uint32_t status;
  uint32_t sample;

  syslog(LOG_INFO, "[mic] capturing %d samples ...\n", n);

  while (count < n)
    {
      status = aud_getreg(AUD_FIFO_STATUS);

      if (!(status & AUD_ADC_FIFO_EMPTY))
        {
          sample = aud_getreg(AUD_ADC_FIFO_PORT);
          g_mic_left[count]  = (int16_t)(sample & 0xffff);
          g_mic_right[count] = (int16_t)((sample >> 16) & 0xffff);
          count++;
        }
    }

  syslog(LOG_INFO, "[mic] capture done: %d pairs\n", count);
  return count;
}

/****************************************************************************
 * Name: compute_rms
 *
 * Description:
 *   Compute RMS of an int16_t buffer.
 *
 ****************************************************************************/

static float compute_rms(const int16_t *buf, int n)
{
  double sum = 0.0;
  int i;

  for (i = 0; i < n; i++)
    {
      sum += (double)buf[i] * (double)buf[i];
    }

  return (float)sqrt(sum / n);
}

/****************************************************************************
 * Name: mic_test
 *
 * Description:
 *   Full mic test: init → capture → print RMS + first 8 samples → deinit.
 *
 ****************************************************************************/

static int mic_test(void)
{
  int n;
  int i;
  float rms_l;
  float rms_r;

  audio_init();

  n = audio_capture(MIC_N_SAMPLES);

  rms_l = compute_rms(g_mic_left, n);
  rms_r = compute_rms(g_mic_right, n);

  syslog(LOG_INFO,
         "[mic] RMS: left=%.1f  right=%.1f\n",
         rms_l, rms_r);

  syslog(LOG_INFO, "[mic] first 8 samples (L, R):\n");

  for (i = 0; i < 8; i++)
    {
      syslog(LOG_INFO, "  [%d] L=%6d  R=%6d\n",
             i, g_mic_left[i], g_mic_right[i]);
    }

  audio_deinit();
  return OK;
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

/****************************************************************************
 * Name: bk7258_mic_main
 *
 * Description:
 *   NSH command: lcdtest mic → ADC dual-channel capture + RMS dump.
 *
 ****************************************************************************/

int bk7258_mic_main(int argc, char *argv[])
{
  return mic_test();
}

